package run.ikaros.finance; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/finance/ledgers/{ledgerId}/exchange-rates") public class ExchangeRateController{private final ExchangeRateService service;public ExchangeRateController(ExchangeRateService s){service=s;}@PostMapping public Mono<ExchangeRateView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody CreateExchangeRateRequest r){return service.create(a,ledgerId,r);}@GetMapping public Flux<ExchangeRateView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.list(a,ledgerId);}}
